    14	/**
    15	 * The JSON wire format of the Game of Life CLI: the {@code aliveCells} field
    16	 * and the {@code [x, y]} encoding of a single cell.
    17	 */
    18	final class GenerationJson {
    19	
    20	    private static final String ALIVE_CELLS = "aliveCells";
    21	
    22	    private static final String STEPS = "steps";
    23	
    24	    private final ObjectMapper mapper = new ObjectMapper();
    25	
    26	    GenerationRequest readRequest(InputStream request) throws IOException {
    27	        JsonNode root = mapper.readTree(request);
    28	        Set<Cell> livingCells = new HashSet<>();
    29	        for (JsonNode cell : root.get(ALIVE_CELLS)) {
    30	            livingCells.add(new Cell(cell.get(0).asInt(), cell.get(1).asInt()));
    31	        }
    32	        return new GenerationRequest(livingCells, root.get(STEPS).asInt());
    33	    }
    34	
    35	    String writeLivingCells(Set<Cell> livingCells) throws IOException {
    36	        ObjectNode response = mapper.createObjectNode();
    37	        ArrayNode aliveCells = response.putArray(ALIVE_CELLS);
    38	        for (Cell cell : sortedByXThenY(livingCells)) {
    39	            ArrayNode coordinates = aliveCells.addArray();
    40	            coordinates.add(cell.x());
    41	            coordinates.add(cell.y());
    42	        }
    43	        return mapper.writeValueAsString(response);
    44	    }
    45	
    46	    private static List<Cell> sortedByXThenY(Set<Cell> livingCells) {
    47	        List<Cell> sorted = new ArrayList<>(livingCells);
    48	        sorted.sort(Comparator.comparingInt(Cell::x).thenComparingInt(Cell::y));
    49	        return sorted;
    50	    }
    51	}
