     6	public class GameOfLife {
     7	
     8	    public Set<Cell> advance(Set<Cell> livingCells, int generations) {
     9	        Set<Cell> population = livingCells;
    10	        for (int generation = 0; generation < generations; generation++) {
    11	            population = nextGeneration(population);
    12	        }
    13	        return population;
    14	    }
    15	
    16	    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
    17	        Set<Cell> nextGeneration = new HashSet<>();
    18	        for (Cell cell : cellsThatCanChange(livingCells)) {
    19	            if (isAliveNextGeneration(cell, livingCells)) {
    20	                nextGeneration.add(cell);
    21	            }
    22	        }
    23	        return nextGeneration;
    24	    }
    25	
    26	    private Set<Cell> cellsThatCanChange(Set<Cell> livingCells) {
    27	        Set<Cell> cells = new HashSet<>(livingCells);
    28	        for (Cell cell : livingCells) {
    29	            cells.addAll(cell.neighbours());
    30	        }
    31	        return cells;
    32	    }
    33	
    34	    private boolean isAliveNextGeneration(Cell cell, Set<Cell> livingCells) {
    35	        int livingNeighbours = countLivingNeighbours(cell, livingCells);
    36	        if (livingCells.contains(cell)) {
    37	            return survives(livingNeighbours);
    38	        }
    39	        return isBorn(livingNeighbours);
    40	    }
    41	
    42	    private boolean survives(int livingNeighbours) {
    43	        return livingNeighbours == 2 || livingNeighbours == 3;
    44	    }
    45	
    46	    private boolean isBorn(int livingNeighbours) {
    47	        return livingNeighbours == 3;
    48	    }
    49	
    50	    private int countLivingNeighbours(Cell cell, Set<Cell> livingCells) {
    51	        int count = 0;
    52	        for (Cell neighbour : cell.neighbours()) {
    53	            if (livingCells.contains(neighbour)) {
    54	                count++;
    55	            }
    56	        }
    57	        return count;
    58	    }
    59	}
